insert into change_headers (id, ts) values (74, '2026-11-18') on duplicate key update ts = values(ts);
insert into change_descriptions (id, lang, description) values (74, 'ru', 'Добавлен Межпланетный сканер аномалий — новая постройка расширения Project Orion, которое пока в бете на тестовых серверах. Он есть в списке построек калькуляторов стоимости и очереди, а у семи компонентов его Центра управления в Расчёте стоимости своя вкладка: там видны стоимость, время и эффект каждого компонента на выбранном уровне.<br>В Калькуляторе производства на вкладке «Одна планета» можно учесть конвертацию ресурсов сканером в литий: включите «МСА» и задайте уровень, скидку, ресурс и загрузку.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (74, 'en', 'Added the Interstellar Anomaly Scanner, a new building of the Project Orion expansion, currently in beta on the test servers. It is in the building lists of the Costs calculator and the Construction queue, and the seven components of its Control Centre have their own tab in the Costs calculator, showing each component''s cost, time and effect at the chosen level.<br>On the "One planet" tab of the Production calculator you can now account for the scanner''s conversion of resources into lithium: tick "IAS" and set the level, discount, resource and workload.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (74, 'pt', 'Adicionado o Sensor de Anomalia Interestelar, um novo edifício da expansão Project Orion, por agora em beta nos servidores de teste. Está na lista de edifícios da Calculadora de Custos e da Fila de construção, e os sete componentes do seu Centro de Controlo têm um separador próprio na Calculadora de Custos, com o custo, o tempo e o efeito de cada componente no nível escolhido.<br>No separador «Um planeta» da Calculadora de Produção já é possível contar com a conversão de recursos em lítio feita pelo sensor: ative «IAS» e indique o nível, o desconto, o recurso e a carga de trabalho.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (74, 'de', 'Neu: der Interstellare Anomalie-Scanner, ein neues Gebäude der Erweiterung Project Orion, die sich derzeit in der Beta auf den Testservern befindet. Er steht in der Gebäudeliste der Kostenberechnung und der Bauwarteschlange, und die sieben Komponenten seines Kontrollzentrums haben in der Kostenberechnung einen eigenen Reiter mit Kosten, Bauzeit und Effekt jeder Komponente auf der gewählten Stufe.<br>In der Produktionsberechnung lässt sich auf dem Reiter „Einen Planeten“ jetzt die Umwandlung von Rohstoffen in Lithium durch den Scanner berücksichtigen: „IAS“ anhaken und Stufe, Rabatt, Rohstoff und Auslastung angeben.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (74, 'pl', 'Dodano Międzygwiezdny Skaner Anomalii – nowy budynek rozszerzenia Project Orion, które jest na razie w becie na serwerach testowych. Znajduje się na liście budynków Kalkulatora kosztów i Kolejki budynków, a siedem komponentów jego Centrum kontrolnego ma w Kalkulatorze kosztów własną zakładkę z kosztem, czasem i efektem każdego komponentu na wybranym poziomie.<br>Na zakładce „Jedna planeta” Kalkulatora produkcji można teraz uwzględnić konwersję surowców na lit przez skaner: zaznacz „IAS” i podaj poziom, zniżkę, surowiec i obciążenie.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (74, 'es', 'Se ha añadido el Escáner de Anomalías Interestelares, un nuevo edificio de la expansión Project Orion, que por ahora está en beta en los servidores de prueba. Aparece en la lista de edificios de la Calculadora de Costes y de la Cola de construcción, y los siete componentes de su Centro de control tienen una pestaña propia en la Calculadora de Costes, con el coste, el tiempo y el efecto de cada componente en el nivel elegido.<br>En la pestaña «Un planeta» de la Calculadora de Producción ya se puede tener en cuenta la conversión de recursos en litio que hace el escáner: marca «IAS» e indica el nivel, el descuento, el recurso y la carga de trabajo.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (74, 'fr', 'Nouveau : le Scanner d''anomalies interstellaire, un bâtiment de l''extension Project Orion, actuellement en bêta sur les serveurs de test. Il figure dans la liste des bâtiments du Calculateur de coûts et de la File de construction, et les sept composants de son Centre de contrôle ont leur propre onglet dans le Calculateur de coûts, avec le coût, la durée et l''effet de chaque composant au niveau choisi.<br>Dans l''onglet « Une planète » du Calculateur de production, la conversion de ressources en lithium par le scanner peut désormais être prise en compte : cochez « IAS » et indiquez le niveau, la remise, la ressource et la charge de travail.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (74, 'it', 'Aggiunto lo Scanner di anomalie interstellari, un nuovo edificio dell''espansione Project Orion, per ora in beta sui server di prova. È nell''elenco degli edifici del Calcolatore di Costi e della Coda di costruzione, e i sette componenti del suo Centro controllo hanno una scheda propria nel Calcolatore di Costi, con costo, tempo ed effetto di ogni componente al livello scelto.<br>Nella scheda «Solo pianeta» del calcolatore Produzione ed energia ora si può tenere conto della conversione di risorse in litio da parte dello scanner: spunta «IAS» e indica livello, sconto, risorsa e carico di lavoro.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (74, 'nl', 'Nieuw: de Interstellaire Anomalieënscanner, een nieuw gebouw uit de uitbreiding Project Orion, die nu in bèta is op de testservers. Hij staat in de gebouwenlijst van de Kostenberekening en de Bouwlijst, en de zeven onderdelen van zijn Controlecentrum hebben in de Kostenberekening een eigen tabblad met de kosten, de tijd en het effect van elk onderdeel op het gekozen niveau.<br>Op het tabblad "Een planeet" van Productie en Energie kun je nu rekening houden met de omzetting van grondstoffen in lithium door de scanner: vink "IAS" aan en geef het niveau, de korting, de grondstof en de werklast op.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (74, 'sk', 'Pridaný Medzihviezdny skener anomálií – nová budova rozšírenia Project Orion, ktoré je zatiaľ v bete na testovacích serveroch. Nájdete ho v zozname budov Kalkulátora cien a Stavby front a sedem komponentov jeho Riadiaceho centra má v Kalkulátore cien vlastnú záložku s cenou, časom a efektom každého komponentu na zvolenej úrovni.<br>Na záložke „Jedna planéta“ Kalkulátora produkcie sa teraz dá zohľadniť premena surovín na lítium skenerom: zaškrtnite „IAS“ a zadajte úroveň, zľavu, surovinu a vyťaženie.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (74, 'tr', 'Yıldızlararası Anomali Tarayıcısı eklendi: Project Orion genişlemesinin, şu anda test sunucularında beta aşamasında olan yeni bir binası. Maliyet Hesaplayıcı ve İnşaat kuyruğu bina listelerinde yer alıyor; Kontrol Merkezi''nin yedi bileşeni ise Maliyet Hesaplayıcı''da kendi sekmesine sahip ve her bileşenin seçilen seviyedeki maliyetini, süresini ve etkisini gösteriyor.<br>Üretim Hesaplayıcı''nın "Tek gezegen" sekmesinde artık tarayıcının kaynakları lityuma dönüştürmesi hesaba katılabiliyor: "IAS" kutusunu işaretleyip seviyeyi, indirimi, kaynağı ve iş yükünü girin.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (74, 'bs', 'Dodan je Skener Međuzvjezdanih Anomalija, nova zgrada proširenja Project Orion, koje je zasad u beti na testnim serverima. Nalazi se na listi zgrada Kalkulatora troškova i Reda izgradnje, a sedam komponenti njegovog Kontrolnog Centra ima u Kalkulatoru troškova svoju karticu s cijenom, vremenom i efektom svake komponente na odabranom nivou.<br>Na kartici „Jedan planet“ Kalkulatora produkcije sada se može uračunati pretvaranje resursa u litij koje radi skener: označite „IAS“ i unesite nivo, popust, resurs i opterećenje.') on duplicate key update description = values(description);
